import{_ as e,H as t,f as l,i}from"./chunks/framework.CBmkDW73.js";const u=JSON.parse('{"title":"TDD（테스트 주도 개발）","description":"","frontmatter":{},"headers":[],"relativePath":"ko/skills/tdd.md","filePath":"ko/skills/tdd.md"}'),r={name:"ko/skills/tdd.md"};function o(d,a,n,s,h,c){return t(),l("div",null,[...a[0]||(a[0]=[i('<h1 id="tdd-테스트-주도-개발" tabindex="-1">TDD（테스트 주도 개발） <a class="header-anchor" href="#tdd-테스트-주도-개발" aria-label="Permalink to &quot;TDD（테스트 주도 개발）&quot;">​</a></h1><p>계획이 승인되면, 각 작업에서 RED → GREEN → 리팩터링을 실행한다. 각 사이클이 git 커밋이 된다.</p><h2 id="빨강" tabindex="-1">빨강 <a class="header-anchor" href="#빨강" aria-label="Permalink to &quot;빨강&quot;">​</a></h2><p>실패하는 테스트를 작성한다. 작업이 완료됐음을 어떻게 알 것인지 선언한다.</p><h2 id="초록" tabindex="-1">초록 <a class="header-anchor" href="#초록" aria-label="Permalink to &quot;초록&quot;">​</a></h2><p>테스트를 통과시키는 최소한의 코드를 작성한다. 설계는 전혀 신경 쓰지 않는다.</p><h2 id="리팩터링" tabindex="-1">리팩터링 <a class="header-anchor" href="#리팩터링" aria-label="Permalink to &quot;리팩터링&quot;">​</a></h2><p>코드를 깔끔하게 만든다. 동작은 변경하지 않는다. 발견하거나 배운 것이 있으면 명세 노트를 업데이트한다.</p><h2 id="문서-동기화" tabindex="-1">문서 동기화 <a class="header-anchor" href="#문서-동기화" aria-label="Permalink to &quot;문서 동기화&quot;">​</a></h2><p>RED-GREEN-리팩터링 각 사이클 후, 커밋 전에 문서를 동기화:</p><ul><li>명세가 존재함 → 실제 상태에 맞게 업데이트한다.</li><li>명세 없음 (소규모 작업) → living docs를 직접 업데이트한다.</li></ul><h2 id="수락" tabindex="-1">수락 <a class="header-anchor" href="#수락" aria-label="Permalink to &quot;수락&quot;">​</a></h2><p>각 작업의 acceptance 조건은 그린 후에 통과해야 한다. 자동으로 확인할 수 없으면 커밋 전에 수동으로 검증한다.</p><h2 id="gate" tabindex="-1">Gate <a class="header-anchor" href="#gate" aria-label="Permalink to &quot;Gate&quot;">​</a></h2><p><strong>여기서 멈춰라:</strong></p><ul><li>테스트가 실패하고 있다.</li><li>Acceptance 기준을 충족할 수 없다.</li><li>코드가 명세와 일치하지 않는다.</li></ul><p>그렇지 않으면 <code>ship</code>으로 진행한다.</p>',17)])])}const _=e(r,[["render",o]]);export{u as __pageData,_ as default};
